// Package resources holds the non-code files embedded into selkit.exe.
//
// Translations live in locales/: the template selkit.pot (regenerated by the i18n catalog test)
// and one <language>.po per translation.
package resources

import "embed"

//go:embed locales/*.po
var Locales embed.FS

// Transliteration systems (translit/*.rules), see internal/translit for the format.
//
//go:embed translit/*.rules
var Translit embed.FS

// The mark built from icon/*.svg by "go generate ./cmd/selkit"; the ICO files are committed
// so that a plain "go build" works without the generator.
var (
	//go:embed icon/selkit.ico
	IconICO []byte
	//go:embed icon/selkit-off.ico
	IconOffICO []byte
	// For the icon theme of a Linux desktop.
	//go:embed icon/selkit.svg
	IconSVG []byte
)
